const needsReview = problems.length > 0 || extraction.needs_review === true;

return [
  {
    json: {
      ...$json,
      extraction_quality_passed: !needsReview,
      needs_review: needsReview,
      validation_problems: problems
    }
  }
];

const metadata = {
  source: $json.source,
  submitter_id: $json.submitter_id,
  channel_id: $json.channel_id,
  message_ts: $json.message_ts,
  message_text: $json.message_text,
  submitted_at: $json.submitted_at,
  receipt_id: $json.receipt_id,
  file_name: $json.file_name,
  mime_type: $json.mime_type
};

const extraction = $json.extraction || {};

const currencyMap = {
  '£': 'GBP',
  'GBP': 'GBP',
  '$': 'USD',
  'USD': 'USD',
  '€': 'EUR',
  'EUR': 'EUR'
};

const currency = currencyMap[extraction.currency] || extraction.currency || 'UNKNOWN';

return [
  {
    json: {
      ...metadata,
      audit_payload: {
        expense_id: $json.receipt_id,
        source: 'slack',
        submitter_id: $json.submitter_id,
        channel_id: $json.channel_id,
        message_ts: $json.message_ts,
