          transaction_date: extraction.transaction_date || '',
          currency,
          subtotal: Number(extraction.subtotal || 0),
          tax: Number(extraction.tax || 0),
          total: Number(extraction.total || 0),
          line_items: Array.isArray(extraction.line_items)
            ? extraction.line_items
            : []
        },

        extraction: {
          confidence: Number(extraction.extraction_confidence || 0),
          unclear_fields: Array.isArray(extraction.unclear_fields)
            ? extraction.unclear_fields
            : [],
          needs_review: extraction.needs_review === true
        }
      }
    }
  }
];

const payload = $json.audit_payload || {};
const receipt = payload.receipt || {};
const extraction = payload.extraction || {};

const total = Number(receipt.total || 0);

// -----------------------------
// Parse receipt transaction date
// -----------------------------
function parseTransactionDate(value) {
  if (!value || typeof value !== 'string') return null;

  // UK format: DD/MM/YYYY
  const uk = value.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (uk) {
    const day = Number(uk[1]);
    const month = Number(uk[2]) - 1;
    const year = Number(uk[3]);
    return new Date(Date.UTC(year, month, day, 12, 0, 0));
  }

  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

// -----------------------------
// Add one calendar month
// -----------------------------
function addOneMonth(date) {
  const result = new Date(date.getTime());
  const originalDay = result.getUTCDate();

  result.setUTCMonth(result.getUTCMonth() + 1);

  // Handle dates such as 31 January -> 28 February
  if (result.getUTCDate() < originalDay) {
    result.setUTCDate(0);
  }

  return result;
}

const transactionDate = parseTransactionDate(receipt.transaction_date);

let submissionDate = null;

if (payload.submitted_at !== null && payload.submitted_at !== undefined) {
  const timestamp = Number(payload.submitted_at);

  if (Number.isFinite(timestamp)) {
    submissionDate = new Date(timestamp * 1000);
  }
}

const cutoffDate = transactionDate
  ? addOneMonth(transactionDate)
  : null;

const cutoffBreached = Boolean(
  transactionDate &&
  submissionDate &&
  submissionDate > cutoffDate
);

// -----------------------------
// Approval thresholds
// Current project rule: £2,000 CFO threshold
// Handbook baseline: >£250 requires advance line-manager approval
// -----------------------------
const cfoApprovalRequired = total >= 2000;
const lineManagerApprovalRequired = total > 250 && total < 2000;

const flags = [];
const approvals = [];

if (cutoffBreached) {
  flags.push('EXPENSE_OUTSIDE_ONE_MONTH_CUTOFF');
}

if (cfoApprovalRequired) {
  flags.push('CFO_APPROVAL_THRESHOLD');
  approvals.push('CFO_APPROVAL');
} else if (lineManagerApprovalRequired) {
  approvals.push('LINE_MANAGER_APPROVAL');
}

if (extraction.needs_review === true) {
  flags.push('EXTRACTION_REQUIRES_REVIEW');
}

if (Array.isArray(extraction.unclear_fields) && extraction.unclear_fields.length > 0) {
  flags.push('UNCLEAR_RECEIPT_FIELDS');
}

const receiptPresent = Boolean(payload.receipt?.receipt_id);

if (!receiptPresent) {
  flags.push('RECEIPT_MISSING');
}

const humanReviewRequired =
  cutoffBreached ||
  cfoApprovalRequired ||
  extraction.needs_review === true ||
  !receiptPresent;

return [
  {
    json: {
      ...$json,
      policy_checks: {
        one_month_cutoff: {
          transaction_date: transactionDate
            ? transactionDate.toISOString().slice(0, 10)
            : null,
          submission_date: submissionDate
            ? submissionDate.toISOString().slice(0, 10)
            : null,
          cutoff_date: cutoffDate
            ? cutoffDate.toISOString().slice(0, 10)
            : null,
          passed: transactionDate && submissionDate
            ? !cutoffBreached
            : null,
          breached: cutoffBreached
        },

        approval: {
          total,
          cfo_threshold: 2000,
          cfo_approval_required: cfoApprovalRequired,
          line_manager_threshold: 250,
          line_manager_approval_required: lineManagerApprovalRequired
        },

        receipt: {
          present: receiptPresent
        },

        flags,
        approvals_required: approvals,
        human_review_required: humanReviewRequired
      }
    }
  }
];

const payload = $json.audit_payload || {};
const policy = $json.policy_checks || {};

return [
  {
    json: {
      ...$json,
      audit_engine_input: {
        expense_id: payload.expense_id,
        submitted_by: payload.submitter_id,
        source: payload.source,
        receipt: payload.receipt,
        extraction: payload.extraction,
        policy_checks: policy,
        audit_context: {
          preliminary_status: policy.human_review_required
            ? 'NEEDS_REVIEW'
            : 'READY_FOR_AUDIT',
          deterministic_flags: policy.flags || [],
          approvals_required: policy.approvals_required || [],
          human_review_required: policy.human_review_required === true
        }
      }
    }
  }
];

const input = $json.audit_engine_input || {};
const receipt = input.receipt || {};
const policy = input.policy_checks || {};
const context = input.audit_context || {};

return [
  {
    json: {
      ...$json,
      audit_reasoning_input: {
        expense_id: input.expense_id,
        submitted_by: input.submitted_by,
        employee_message: input.receipt?.message_text || $json.message_text || '',
        merchant: receipt.merchant || '',
        transaction_date: receipt.transaction_date || '',
        currency: receipt.currency || '',
        subtotal: Number(receipt.subtotal || 0),
        tax: Number(receipt.tax || 0),
        total: Number(receipt.total || 0),
        line_items: Array.isArray(receipt.line_items)
          ? receipt.line_items
          : [],
        deterministic_flags: context.deterministic_flags || policy.flags || [],
        approvals_required: context.approvals_required || policy.approvals_required || [],
        human_review_required: context.human_review_required === true || policy.human_review_required === true
      }
    }
  }
];

